add_action( 'admin_menu', 'perfectpixel_disable_site_editor_menu', 999 );
add_action( 'admin_init', 'perfectpixel_disable_site_editor_page' );
add_action( 'admin_bar_menu', 'perfectpixel_disable_site_editor_bar', 999 );

function perfectpixel_disable_site_editor_menu() {
	remove_submenu_page( 'themes.php', 'site-editor.php' );
}

function perfectpixel_disable_site_editor_page() {
	global $pagenow;
	if ( 'site-editor.php' === $pagenow ) {
		wp_safe_redirect( admin_url() );
		exit;
	}
}

function perfectpixel_disable_site_editor_bar( $wp_admin_bar ) {
	$wp_admin_bar->remove_node( 'site-editor' );
}
